using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using McpServer;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    .AddHttpClient("WeatherApi", client =>
    {
        client.BaseAddress = new Uri("https://api.open-meteo.com/");
    });

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();

using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly IHttpClientFactory _httpClientFactory;

    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool(Name = "get_weather")]
    [Description("Get current weather for a location by latitude and longitude.")]
    public async Task<string> GetWeatherAsync(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var client = _httpClientFactory.CreateClient("WeatherApi");

        var response = await client.GetAsync(
            $"v1/forecast?latitude={latitude}&longitude={longitude}&current_weather=true");

        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        var weather = json.GetProperty("current_weather");

        return $"Temperature: {weather.GetProperty("temperature")}°C, " +
               $"Wind: {weather.GetProperty("windspeed")} km/h";
    }

    [McpServerTool(Name = "get_geocode")]
    [Description("Search for a location name and return its coordinates.")]
    public async Task<string> GetGeocodeAsync(
        [Description("City or place name to search for")] string name)
    {
        var client = _httpClientFactory.CreateClient("WeatherApi");

        var response = await client.GetAsync(
            $"v1/forecast?latitude=0&longitude=0&current_weather=true");
        // In production, use a real geocoding API

        return $"Searched for: {name} (stub - replace with real geocoding)";
    }
}

